n = int(input())
if n <= 1:
    print("Not Prime")
else:
    is_prime = True
    limit = int(n ** 0.5)
    for d in range(2, limit + 1):
        if n % d == 0:
            is_prime = False
            break
    print("Prime" if is_prime else "Not Prime")

n = int(input())
if n < 0:
    print("Not Palindrome")
else:
    original = n
    rev = 0
    while n > 0:
        rev = rev * 10 + (n % 10)
        n //= 10
    print("Palindrome" if rev == original else "Not Palindrome")

n = int(input())
if n <= 1:
    print("Not Perfect")
else:
    total = 1
    limit = int(n ** 0.5)
    for d in range(2, limit + 1):
        if n % d == 0:
            total += d
            pair = n // d
            if pair != d:
                total += pair
    print("Perfect" if total == n else "Not Perfect")

n = int(input())
if n == 0:
    print("0")
else:
    bits = []
    while n > 0:
        bits.append(str(n % 2))
        n //= 2
    bits.reverse()
    print("".join(bits))

n = int(input())
if n < 2:
    print("None")
else:
    is_prime = [True] * (n + 1)
    is_prime[0] = False
    is_prime[1] = False
    for p in range(2, int(n ** 0.5) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
    primes = [str(i) for i in range(2, n + 1) if is_prime[i]]
    print(" ".join(primes))

