def is_prime(x):
    if x < 2:
        return False
    for d in range(2, int(x ** 0.5) + 1):
        if x % d == 0:
            return False
    return True

n = int(input())
found = False
for p in range(2, n // 2 + 1):
    if is_prime(p) and is_prime(n - p):
        print(f"{p} + {n - p}")
        found = True
        break
if not found:
    print("None")
